import six
from abc import ABCMeta, abstractmethod
import datetime
import time
from functools import partial
import re
import logging
from multiprocessing import Lock
from taf.trafficgenerator.iperf.host import RemoteADBExecutableResources
from taf.trafficgenerator.iperf.exceptions import IperfStartFailure, IperfStopFailure, IperfLogFolderNotExist


@six.add_metaclass(ABCMeta)
class Commands(object):
    def __init__(self, iperf_options, host, logger=None):
        self._iperf_options = iperf_options
        self._host = host
        self._logger = logger or logging

    @property
    def netstat_options(self):
        raise NotImplementedError()

    def query_pid_by_port(self):
        cmd = self._generate_query_pid_command()
        out = self._host.execute(cmd)
        # output from ue host
        # b'tcp       0      0 0.0.0.0:5001            0.0.0.0:*               LISTEN      24658/iperf\r\n'
        # b'udp       0      0 0.0.0.0:5001            0.0.0.0:*                           20767/iperf\r\n'
        # 'tcp        0      0 0.0.0.0:5001            0.0.0.0:*               LISTEN      7362/iperf\r\n'
        # 'udp        0      0 0.0.0.0:5001            0.0.0.0:*                           7212/iperf\r\n'
        # 'tcp        0      0 :::54009                :::*                    LISTEN      2177/iperf3'
        # output from appserver host(CentOS)
        # b'udp        0      0 10.57.163.51:5001       0.0.0.0:*                           24742/iperf\n'
        # b'udp        0      0 10.57.163.51:5001       172.250.186.64:54428    ESTABLISHED 24742/iperf\n'
        # b'udp        0      0 10.57.163.51:54857      172.250.186.64:5001     ESTABLISHED 24807/iperf\n'
        # b'tcp6       0      0 :::54009                :::*                    LISTEN      1564/iperf3'
        # output from Windows host
        # 'TCP    0.0.0.0:54001          0.0.0.0:0              LISTENING       31704'
        # 'TCP    10.57.150.116:54001    10.57.157.12:56686     ESTABLISHED     31704'
        # 'UDP    0.0.0.0:54001          *:*                                    13876'
        self._logger.debug("output from command {} is: {}".format(cmd, out))
        if isinstance(out, bytes):
            split_str = b'\r\n' if b'\r' in out else b'\n'
        else:
            split_str = '\r\n' if '\r' in out else '\n'
        lines = out.split(split_str)
        pids = []
        for line in lines:
            if not line:
                continue
            pid = self._analyze_netstat_line(line)
            if pid:
                pids.append(pid)
        return pids

    @abstractmethod
    def force_kill(self, pid):
        raise NotImplementedError()

    def force_port_available(self):
        pid_list = self.query_pid_by_port()
        self._logger.info('iperf process with the port in use: {}'.format(pid_list))
        for pid in pid_list:
            self.force_kill(pid)
        self._logger.info('force the port in use available by kill iperf process: {}'.format(pid_list))

    def _generate_query_pid_command(self):
        """Generate the command of querying iperf pid, override it"""
        raise NotImplementedError()

    @staticmethod
    def _get_pid(line, pattern_str):
        if isinstance(line, bytes):
            pattern_str = pattern_str.encode('utf-8')
        pattern = re.compile(pattern=pattern_str)
        result = pattern.match(line)
        if not result:
            return None
        return int(result.groupdict()['pid'])

    def _analyze_netstat_line(self, line):
        pattern = r'.*[\d\.:]+:{port}'.format(port=self._iperf_options.port) + r'\s+[\d:*].*\s{1,}(?P<pid>\d+)/iperf'
        return self._get_pid(line, pattern)


class LinuxCommands(Commands):

    @property
    def netstat_options(self):
        if self._iperf_options.is_iperf3() and self._iperf_options.is_server_options():
            return "-anp"
        else:
            if self._iperf_options.udp:
                return '-anpu'
            else:
                return '-anpt'

    def force_kill(self, pid):
        force_cmd = 'kill -9 {pid}'.format(pid=pid)
        self._host.stop_from_command(force_cmd)

    def _generate_query_pid_command(self):
        filter_str = '-E .*:{port}.*/iperf'.format(port=self._iperf_options.port)
        cmd = "netstat {options} | grep {filter_str}".format(options=self.netstat_options, filter_str=filter_str)
        return cmd


class WindowsCommands(Commands):

    @property
    def netstat_options(self):
        return "-ano"

    def force_kill(self, pid):
        force_cmd = 'TASKKILL /T /F /PID {pid}'.format(pid=pid)
        self._host.execute(force_cmd)

    def _generate_query_pid_command(self):
        cmd = "netstat {options} | findstr {port}".format(options=self.netstat_options, port=self._iperf_options.port)
        return cmd

    def _analyze_netstat_line(self, line):
        pattern = r'.*[\d\.:]+:{port}'.format(port=self._iperf_options.port) + r'\s+[\d:*].*\s{1,}(?P<pid>\d+)'
        return self._get_pid(line, pattern)


class AdbCommands(LinuxCommands):
    @property
    def serial_number_option(self):
        return ' -s {}'.format(self._iperf_options.serial_number) if self._iperf_options.serial_number else ''

    def _generate_adb_command(self, command):
        return 'adb{} shell {}'.format(self.serial_number_option, command)

    def _generate_query_pid_command(self):
        cmd = super(AdbCommands, self)._generate_query_pid_command()
        cmd = self._generate_adb_command(cmd)
        return cmd


class RemoteAdbCommands(AdbCommands):

    def force_kill(self, pid):
        force_cmd = self._generate_adb_command('kill -9 {pid}'.format(pid=pid))
        self._host.stop_from_command(force_cmd)

    def _analyze_netstat_line(self, line):
        pattern = '.*:{port}.*'.format(port=self._iperf_options.port) + r'\s{1,}(?P<pid>\d+)/iperf'
        return self._get_pid(line, pattern)


class LocalAdbCommands(AdbCommands):

    def force_kill(self, pid):
        force_cmd = self._generate_adb_command('kill -9 {pid}'.format(pid=pid))
        self._host.execute(force_cmd)


@six.add_metaclass(ABCMeta)
class IperfCommands(object):
    def __init__(self, iperf_options, host, default_temporary_log, logger=None):
        self._iperf_options = iperf_options
        self._temp_log_path = None
        self._host = host
        self._default_temporary_log = default_temporary_log
        self._logger = logger or logging

    @staticmethod
    def _get_current_time():
        current_time = datetime.datetime.now()
        return current_time.strftime('%Y%m%d%H%M%S')

    def _generate_temporary_log_name(self):
        host = self._iperf_options.server_ip
        if self._iperf_options.is_server_options():
            side = 'server'
            if not host:
                self._logger.info('iperf server did not specify the interface to bind')
                host = self._host.hostname
        else:
            side = 'client'

        if self._iperf_options.is_iperf3():
            version = 3
        else:
            version = 2

        return 'iperf{version}_{side}_{host}_{port}_{timestamp}.log'.format(
            version=version,
            side=side,
            host=host,
            port=self._iperf_options.port or 5001,
            timestamp=self._get_current_time()
        )

    def _generate_temporary_log_path(self):
        """generate a log file for saving iperf log temporarily"""
        return self._default_temporary_log.get_log_path(self._generate_temporary_log_name())

    @property
    def start_command_template(self):
        raise NotImplementedError

    @property
    def pid_extractor(self):
        return None

    @property
    def temp_log_path(self):
        return self._temp_log_path

    @property
    def temporary_log_dir(self):
        return self._default_temporary_log.default_dir

    @abstractmethod
    def start_iperf(self, log_path=None):
        """

        """

    def _prepare_temporary_log(self, log_path=None):
        """Generate the option of starting iperf command, can be overrode """

        if not log_path:
            if not self._host.mkdir(self.temporary_log_dir):
                raise IperfLogFolderNotExist("failed to create temporary log directory {}".
                                             format(self.temporary_log_dir))
        self._temp_log_path = log_path or self._generate_temporary_log_path()

    def _start_iperf_daemon(self, log_path=None, shell=False):
        self._prepare_temporary_log(log_path)
        self._logger.info("starting iperf daemon, iperf: {}, options: {}".
                          format(self._iperf_options.iperf_path, str(self._iperf_options)))
        executable_resources = self._host.start_daemon(executable=self._iperf_options.iperf_path,
                                                       log_path=self._temp_log_path,
                                                       options=self._iperf_options,
                                                       command_template=self.start_command_template,
                                                       pid_extractor=self.pid_extractor,
                                                       shell=shell)
        return executable_resources

    def _soft_stop_iperf(self, executable_resources):
        executable_resources.release()

    def _try_until_times(self, act, interval=1, trials=10):
        result = True
        while trials:
            trials = trials - 1
            result = act()
            if not result:
                time.sleep(interval)
                continue
            return result
        return result

    def _check_iperf_dead(self, pid):
        return not self.check_iperf_alive(pid)

    def stop_iperf(self, executable_resources, timeout, force=False):
        self._logger.info("stopping iperf, pid: {}".format(executable_resources.pid))

        check_dead = partial(self._check_iperf_dead, executable_resources.pid)
        if not force:
            self._soft_stop_iperf(executable_resources)
            if self._try_until_times(check_dead, trials=timeout / 1):
                return

        self.force_kill(executable_resources.pid)
        if not self._try_until_times(check_dead, trials=timeout / 1):
            raise IperfStopFailure("failed to stop iperf process {}".format(executable_resources.pid))

    def check_iperf_alive(self, pid):
        return self._host.pid_exists(pid)


class LinuxIperfCommands(IperfCommands, LinuxCommands):

    @property
    def start_command_template(self):
        return 'nohup {} 2>&1 & echo $!'

    @property
    def pid_extractor(self):
        return self._extract_started_pid

    def _extract_started_pid(self, response):
        try:
            pid = int(response.strip())
        except ValueError:
            self._logger.debug('response from start is invalid, {}'.format(response))
            return None
        return pid

    def start_iperf(self, log_path=None):
        executable_resources = self._start_iperf_daemon(log_path)
        if not executable_resources or not self.check_iperf_alive(executable_resources.pid):
            raise IperfStartFailure('Iperf process with pid {} not exist'.format(
                executable_resources.pid if executable_resources else None))
        return executable_resources


class WindowsIperfCommands(IperfCommands, WindowsCommands):

    @property
    def start_command_template(self):
        return '{} 2>&1'

    def start_iperf(self, log_path=None):
        executable_resources = self._start_iperf_daemon(log_path)
        if not executable_resources or not self.check_iperf_alive(executable_resources.pid):
            raise IperfStartFailure('Iperf process with pid {} not exist'.format(
                executable_resources.pid if executable_resources else None))
        return executable_resources

    def check_iperf_alive(self, pid):
        out = self._host.execute('TASKLIST|FINDSTR {pid}'.format(pid=pid))
        return str(pid) in str(out)


mutex = Lock()


class AdbIperfCommands(LinuxIperfCommands):

    @property
    def start_command_template(self):
        return 'adb{} shell '.format(self.serial_number_option) + '{} 2>&1 &'


class RemoteAdbIperfCommands(AdbIperfCommands, RemoteAdbCommands):

    @property
    def pid_extractor(self):
        return None

    def start_iperf(self, log_path=None):
        try:
            mutex.acquire()
            old_pids = self.query_pid_by_port()
            self._start_iperf_daemon(log_path)
            new_pids = self.query_pid_by_port()
            pid = self._find_new_pid(old_pids, new_pids)
        finally:
            mutex.release()
        if not pid:
            raise IperfStartFailure("cannot find new pid for iperf")
        return RemoteADBExecutableResources(pid, self._host, serial_number=self._iperf_options.serial_number)

    def _find_new_pid(self, old_pids, new_pids):
        new_diff_pids = set(new_pids) - set(old_pids)
        if not new_diff_pids:
            self._logger.error('there is no new pid in {}'.format(new_pids))
            return None

        if len(new_diff_pids) == 1:
            return new_diff_pids.pop()

        self._logger.warning("find more than one new pids {} for iperf".format(new_diff_pids))
        try:
            return max(new_diff_pids)
        except ValueError:
            self._logger.error('there is invalid pid(s) in {}'.format(new_pids))
            return None

    def check_iperf_alive(self, pid):
        check_cmd = self._generate_adb_command('ps -p {pid}'.format(pid=pid))
        out = self._host.execute(check_cmd)
        return str(pid) in str(out)


class LocalAdbIperfCommands(AdbIperfCommands, LocalAdbCommands):
    def start_iperf(self, log_path=None):
        # this pid is not the iperf pid, but the parent pid on UE PC
        executable_resources = self._start_iperf_daemon(log_path, shell=True)
        if not executable_resources or not executable_resources.pid:
            raise IperfStartFailure("cannot find new pid for iperf")
        return executable_resources
